class Solution:
    def maxFrequencyScore(self, nums: List[int], k: int) -> int:
        nums.sort()
        n = len(nums)

        prefix = [0] * (n + 1)
        for i, num in enumerate(nums):
            prefix[i + 1] = prefix[i] + num

        def can(target_freq: int) -> bool:
            for left in range(n - target_freq + 1):
                right = left + target_freq - 1
                mid = (left + right) // 2
                median = nums[mid]

                left_cost = median * (mid - left + 1) - (prefix[mid + 1] - prefix[left])
                right_cost = (prefix[right + 1] - prefix[mid + 1]) - median * (right - mid)

                if left_cost + right_cost <= k:
                    return True

            return False

        low, high = 1, n
        answer = 1

        while low <= high:
            mid = (low + high) // 2
            if can(mid):
                answer = mid
                low = mid + 1
            else:
                high = mid - 1

        return answer
