            ans = min(ans, r + 1 + dp(n // 5))
            inc = (5 - r) % 5
            ans = min(ans, inc + 1 + dp((n + inc) // 5))

            r = n % 11
            ans = min(ans, r + 1 + dp(n // 11))
            inc = (11 - r) % 11
            ans = min(ans, inc + 1 + dp((n + inc) // 11))

            return ans

