        dq = deque()

        for i, a in enumerate(A):
            val = a - i
            while dq and dq[-1][1] >= val:
                dq.pop()
            dq.append((i, val))

            start = i - k + 1
            while dq and dq[0][0] < start:
                dq.popleft()

            if start >= 0:
                left_min[i] = dq[0][1]

        right_min = [0] * N
        dq = deque()

        for i, a in enumerate(A):
            val = a + i
            while dq and dq[-1][1] >= val:
                dq.pop()
            dq.append((i, val))

            start = i - k + 1
            while dq and dq[0][0] < start:
                dq.popleft()

            if start >= 0:
                right_min[start] = dq[0][1]

        for c in range(k - 1, N - k + 1):
            if left_min[c] >= k - c and right_min[c] >= k + c:
                return True

        return False

    low = 1
    high = (N + 1) // 2
    answer = 1

