            for j in range(N):
                dkj = dk[j]
                if dkj == INF:
                    continue
                nd = dik + dkj
                if nd < di[j]:
                    di[j] = nd

    size = 1 << N
    full = size - 1

    bits = [None] * size
    bits[0] = b""
    byte_for_lsb = [b""] * size
    for i in range(N):
        byte_for_lsb[1 << i] = bytes((i,))

    for mask in range(1, size):
        lsb = mask & -mask
        bits[mask] = bits[mask ^ lsb] + byte_for_lsb[lsb]

    to = [[0] * N for _ in range(N)]
    for v in range(N):
        col = to[v]
        for u in range(N):
            col[u] = dist[u][v]

    pow2 = [1 << i for i in range(N)]
    dp = [INF] * (N * size)

    for i in range(N):
        dp[(1 << i) * N + i] = 0

    dp_local = dp
    bits_local = bits
    to_local = to
    pow2_local = pow2
    n = N
    inf = INF

