from typing import List

class Solution:
    def canSortArray(self, nums: List[int]) -> bool:
        arr = nums[:]
        n = len(arr)
        i = 0

        while i < n:
            bits = bin(arr[i]).count("1")
            j = i

            while j < n and bin(arr[j]).count("1") == bits:
                j += 1

            arr[i:j] = sorted(arr[i:j])
            i = j

        return all(arr[i] <= arr[i + 1] for i in range(n - 1))
